<?php if(is_role('Dispatcher','Administrator')&&in_array($r['status'],['Approved','Dispatched','Returned'])):$action=match($r['status']){'Approved'=>'dispatch','Dispatched'=>'receive',default=>'complete'};?><section class="panel"><div class="panel-heading"><h2><?=match($action){'dispatch'=>'Release vehicle','receive'=>'Record return',default=>'Finalize trip'}?></h2></div><form action="actions.php" method="post" class="form-body stack"><?=csrf()?><input type="hidden" name="action" value="<?=$action?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="return_to" value="index.php?page=request&id=<?=$r['id']?>"><?php if($action!=='complete'):?><label>Actual <?=$action==='dispatch'?'departure':'return'?> time<input type="datetime-local" name="actual_time" required value="<?=date('Y-m-d\TH:i')?>"></label><label>Odometer <?=$action==='dispatch'?'out':'in'?> (km)<input type="number" name="odometer_<?=$action==='dispatch'?'out':'in'?>" min="<?=$action==='dispatch'?(int)one('SELECT odometer FROM vehicles WHERE id=?',[$r['vehicle_id']])['odometer']:(int)$m['odometer_out']?>" required></label><label>Vehicle condition<input name="condition_text" required maxlength="160" value="Good"></label><label>Remarks / damage / incidents<textarea name="remarks" rows="3" maxlength="2000"></textarea></label><?php else:?><p class="muted">Confirm that the recorded mileage, vehicle condition, and return information are complete.</p><?php endif?><button class="btn primary"><?=match($action){'dispatch'=>'Confirm vehicle release','receive'=>'Confirm vehicle return',default=>'Mark trip completed'}?></button></form></section><?php endif?>
